(()=>{'use strict';
 const ref=window.OGE_GRAMMAR_REFERENCE_V18, p=window.OGE_PROGRAM;
 if(!ref?.guides || !p?.grammarGroups){console.error('v37: dependent grammar library not found');return;}
 const pages={"have got / has got":"<article id=\"rule-theory\" class=\"gb37\" lang=\"ru\"><header class=\"gb37-hero\"><small>БАЗОВАЯ ГРАММАТИКА · КРИСТИНА · ОГЭ 2027</small><h2>Have got / has got: наличие и отношения</h2><p>Когда говорим, что <b>у кого-то есть</b> вещь, родственника, признак или симптом, сначала определяем значение, а затем выбираем форму. <b>Have got</b> — не то же самое, что Present Perfect для событий.</p></header><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">01 · Смысл</div><h3>Что именно «есть»?</h3><div class=\"gb37-pair\"><div class=\"gb37-card\"><b>Владение</b><p lang=\"en\">I <em>have got</em> a bike.</p><small>У меня есть велосипед.</small></div><div class=\"gb37-card\"><b>Родственные связи</b><p lang=\"en\">She <em>has got</em> two brothers.</p><small>У неё два брата.</small></div><div class=\"gb37-card\"><b>Признак / состояние</b><p lang=\"en\">He <em>has got</em> blue eyes.</p><small>У него голубые глаза.</small></div><div class=\"gb37-card\"><b>Наличие симптома (разг.)</b><p lang=\"en\">I<em>’ve got</em> a headache.</p><small>У меня болит голова.</small></div></div><div class=\"gb37-note\">В этих значениях <b>have got</b> обычно описывает настоящее состояние. Для привычных действий <b>have breakfast</b> или <b>have a shower</b> нужна другая конструкция: <b>I have breakfast at seven</b>, а не <s>I have got breakfast at seven</s>.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">02 · Формы</div><h3>Как выбрать have или has</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>Кто?</th><th>Утверждение</th><th>Отрицание</th><th>Вопрос</th><th>Краткий ответ</th></tr></thead><tbody><tr><td>I / you / we / they</td><td>We <b>have got</b> time.</td><td>We <b>haven’t got</b> time.</td><td><b>Have</b> you <b>got</b> time?</td><td>Yes, I have. / No, I haven’t.</td></tr><tr><td>he / she / it</td><td>She <b>has got</b> a sister.</td><td>She <b>hasn’t got</b> a sister.</td><td><b>Has</b> she <b>got</b> a sister?</td><td>Yes, she has. / No, she hasn’t.</td></tr></tbody></table></div><div class=\"gb37-note\">Вопрос строится перестановкой: <b>Have/Has + подлежащее + got ...?</b> Не добавляй do/does к <i>have got</i>: <s>Does she has got a bike?</s> → <b>Has she got a bike?</b>.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">03 · Выбор конструкции</div><h3>Have, have got и Present Perfect: три разных случая</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>Смысл</th><th>Подходящая форма</th><th>Почему</th></tr></thead><tbody><tr><td>Обладание сейчас</td><td>She <b>has got</b> a car. / She <b>has</b> a car.</td><td>В разговорном BrE обе формы нормальны; AmE чаще использует have.</td></tr><tr><td>Регулярное действие</td><td>She <b>has</b> lunch at noon.</td><td>Здесь have = ест, а не владеет.</td></tr><tr><td>Совершившееся действие</td><td>She <b>has bought</b> a car.</td><td>Это Present Perfect: has + V3; слово got не нужно.</td></tr><tr><td>Прошедшее владение</td><td>She <b>had</b> a car when she lived in Kazan.</td><td>Для прошлого обычно используем had.</td></tr></tbody></table></div><div class=\"gb37-note\">Если в американском английском говорят <b>Do you have a car?</b>, это не ошибка. В британском также естественно <b>Have you got a car?</b>.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">04 · Контекст</div><h3>Вопрос, отрицание и короткий ответ</h3><div class=\"gb37-example-set\"><div class=\"gb37-example\"><p lang=\"en\">Have you got any homework? — Yes, I have.</p><small>У тебя есть домашняя работа? — Да.</small></div><div class=\"gb37-example\"><p lang=\"en\">Has Max got a pet? — No, he hasn’t.</p><small>У Макса есть питомец? — Нет.</small></div><div class=\"gb37-example\"><p lang=\"en\">How many cousins have you got?</p><small>Сколько у тебя двоюродных братьев и сестёр?</small></div></div><div class=\"gb37-note\"><b>How many ...?</b> спрашивает количество — на него обычно отвечают числом: <b>Three</b>, а не одним <i>Yes/No</i>.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">05 · Исправь</div><h3>Частые ошибки</h3><div class=\"gb37-errors\"><div><span class=\"gb37-wrong\">✕ She have got a dog.</span><span class=\"gb37-right\">✓ She has got a dog.</span><p>She = третье лицо единственного числа → has.</p></div><div><span class=\"gb37-wrong\">✕ Has he a brother got?</span><span class=\"gb37-right\">✓ Has he got a brother?</span><p>Got в вопросе стоит сразу после подлежащего.</p></div><div><span class=\"gb37-wrong\">✕ I have got breakfast at 8 every day.</span><span class=\"gb37-right\">✓ I have breakfast at 8 every day.</span><p>Повторяющееся действие: обычный have в Present Simple.</p></div></div></section><div class=\"gb37-outro\"><b>Проверь себя:</b> закрой таблицу и придумай по одному правильному примеру из каждой рассмотренной ситуации. Затем перейди к упражнениям ниже.</div></article>","There is / There are":"<article id=\"rule-theory\" class=\"gb37\" lang=\"ru\"><header class=\"gb37-hero\"><small>БАЗОВАЯ ГРАММАТИКА · КРИСТИНА · ОГЭ 2027</small><h2>There is / There are: вводим новую информацию</h2><p>В русском можно сказать «На столе книга». В английском, когда мы сообщаем о наличии нового предмета в каком-то месте, часто используем <b>there is / there are</b>. Это не местоимение «там» и не то же самое, что <b>it is</b>.</p></header><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">01 · Ситуация</div><h3>Что уже известно слушателю?</h3><div class=\"gb37-pair\"><div class=\"gb37-card\"><b>Предмет появляется впервые</b><p lang=\"en\">There <em>is</em> a letter on the desk.</p><small>На столе лежит письмо. Мы впервые сообщаем о нём.</small></div><div class=\"gb37-card\"><b>Говорим об уже известном предмете</b><p lang=\"en\">The letter <em>is</em> on the desk.</p><small>Письмо на столе. Речь о конкретном письме.</small></div></div><div class=\"gb37-note\">Смысловая последовательность: <b>есть нечто → где?</b> Поэтому в конструкции there + be новое существительное идёт после be.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">02 · Согласование</div><h3>Один предмет, несколько, вещество</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>Что стоит после be</th><th>Форма</th><th>Пример и перевод</th></tr></thead><tbody><tr><td>Исчисляемое в единственном числе</td><td><b>There is</b></td><td>There is <b>a</b> window. — Есть окно.</td></tr><tr><td>Множественное число</td><td><b>There are</b></td><td>There are <b>three</b> windows. — Есть три окна.</td></tr><tr><td>Неисчисляемое</td><td><b>There is</b></td><td>There is <b>some</b> water. — Есть немного воды.</td></tr></tbody></table></div><div class=\"gb37-note\">В разговорной речи встречается <b>There’s two people outside</b>, но для письменной экзаменационной нормы выбирай <b>There are two people</b>.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">03 · Построй сам</div><h3>Отрицание, вопрос, короткий ответ</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>Тип</th><th>Единственное число</th><th>Множественное число</th></tr></thead><tbody><tr><td>Отрицание</td><td>There <b>isn’t</b> a bus.</td><td>There <b>aren’t</b> any buses.</td></tr><tr><td>Вопрос</td><td><b>Is there</b> a bus?</td><td><b>Are there</b> any buses?</td></tr><tr><td>Краткий ответ</td><td>Yes, there is. / No, there isn’t.</td><td>Yes, there are. / No, there aren’t.</td></tr><tr><td>Количество</td><td>How much water <b>is there</b>?</td><td>How many buses <b>are there</b>?</td></tr></tbody></table></div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">04 · Не путай</div><h3>There is / It is / They are</h3><div class=\"gb37-pair\"><div class=\"gb37-card\"><b>There is → существование</b><p lang=\"en\">There is a café near my house.</p><small>Рядом с моим домом есть кафе.</small></div><div class=\"gb37-card\"><b>It is → описание известного</b><p lang=\"en\">It is very popular.</p><small>Оно очень популярно. Об этом кафе уже известно.</small></div></div><div class=\"gb37-note\">Нельзя заменить <b>There is a café</b> на <b>It is a café</b> без изменения смысла: второе предложение значит «Это кафе».</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">05 · Особые ситуации</div><h3>Some, any, no; списки; времена</h3><div class=\"gb37-example-set\"><div class=\"gb37-example\"><p lang=\"en\">There is no milk. = There isn’t any milk.</p><small>Молока нет. Две отрицательные конструкции, но не двойное отрицание.</small></div><div class=\"gb37-example\"><p lang=\"en\">There was a storm yesterday.</p><small>Вчера была буря: was вместо is.</small></div><div class=\"gb37-example\"><p lang=\"en\">There will be a test tomorrow.</p><small>Завтра будет контрольная: will be.</small></div></div><div class=\"gb37-note\">Если перечисление смешанное, формальная согласованность может зависеть от структуры фразы: <b>There is a chair and two tables</b> распространено, потому что ближайший элемент — a chair. Для учебных заданий лучше не использовать неоднозначные перечисления.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">06 · Проверь</div><h3>Распространённые ошибки</h3><div class=\"gb37-errors\"><div><span class=\"gb37-wrong\">✕ There are some milk.</span><span class=\"gb37-right\">✓ There is some milk.</span><p>Milk — неисчисляемое.</p></div><div><span class=\"gb37-wrong\">✕ Are there a cinema?</span><span class=\"gb37-right\">✓ Is there a cinema?</span><p>A cinema — единственное число.</p></div><div><span class=\"gb37-wrong\">✕ There is no any food.</span><span class=\"gb37-right\">✓ There is no food. / There isn’t any food.</span><p>Не совмещай no и any в такой конструкции.</p></div></div></section><div class=\"gb37-outro\"><b>Проверь себя:</b> закрой таблицу и придумай по одному правильному примеру из каждой рассмотренной ситуации. Затем перейди к упражнениям ниже.</div></article>","Личные и притяжательные местоимения":"<article id=\"rule-theory\" class=\"gb37\" lang=\"ru\"><header class=\"gb37-hero\"><small>БАЗОВАЯ ГРАММАТИКА · КРИСТИНА · ОГЭ 2027</small><h2>Личные и притяжательные местоимения: кто, кого, чей?</h2><p><b>Местоимение</b> — слово, которое указывает на человека, предмет или принадлежность, не повторяя его название: <b>Maria → she</b>, <b>Maria’s bag → her bag / hers</b>. Разные формы нужны потому, что слово выполняет <b>разную роль в предложении</b>.</p></header><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">01 · Определения</div><h3>Что такое личные и притяжательные местоимения?</h3><div class=\"gb37-pair\"><div class=\"gb37-card\"><b>Личные: называют участника</b><p lang=\"en\"><em>She</em> knows <em>him</em>.</p><small>Она знает его. She выполняет действие; him — тот, на кого оно направлено.</small></div><div class=\"gb37-card\"><b>Притяжательные: показывают принадлежность</b><p lang=\"en\">This is <em>her</em> book. The book is <em>hers</em>.</p><small>Это её книга. Книга принадлежит ей.</small></div></div><div class=\"gb37-note\">Личные местоимения бывают <b>подлежащими (subject)</b> и <b>дополнениями (object)</b>. Притяжательные бывают <b>определителями перед существительным</b> и <b>самостоятельными формами</b>.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">02 · Полная таблица</div><h3>Четыре роли одного участника</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>Кто?</th><th>Перед глаголом (subject)</th><th>После глагола/предлога (object)</th><th>Перед существительным</th><th>Без существительного</th></tr></thead><tbody><tr><td>я</td><td>I</td><td>me</td><td>my</td><td>mine</td></tr><tr><td>ты/вы</td><td>you</td><td>you</td><td>your</td><td>yours</td></tr><tr><td>он</td><td>he</td><td>him</td><td>his</td><td>his</td></tr><tr><td>она</td><td>she</td><td>her</td><td>her</td><td>hers</td></tr><tr><td>оно</td><td>it</td><td>it</td><td>its</td><td>—</td></tr><tr><td>мы</td><td>we</td><td>us</td><td>our</td><td>ours</td></tr><tr><td>они</td><td>they</td><td>them</td><td>their</td><td>theirs</td></tr></tbody></table></div><div class=\"gb37-note\">Самостоятельное притяжательное для <b>it</b> в обычном употреблении отсутствует. Не путай <b>its</b> (его/её принадлежность) и <b>it’s</b> (= it is / it has).</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">03 · Схема роли</div><h3>Покажи стрелкой, кто действует и на кого</h3><div class=\"gb37-svo\"><span class=\"gb37-role gb37-role-s\">S · кто действует<br><b>She</b></span><span class=\"gb37-role gb37-role-v\">V · что делает<br><b>helps</b></span><span class=\"gb37-role gb37-role-o\">O · кому помогает<br><b>me</b></span></div><div class=\"gb37-example-set\"><div class=\"gb37-example\"><p lang=\"en\">She helps me.</p><small>Она помогает мне.</small></div><div class=\"gb37-example\"><p lang=\"en\">I help her.</p><small>Я помогаю ей. Роли поменялись — формы тоже.</small></div><div class=\"gb37-example\"><p lang=\"en\">He gave the tickets to us.</p><small>Он отдал билеты нам. После to нужно us, не we.</small></div></div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">04 · Притяжательные</div><h3>My или mine? Her или hers?</h3><div class=\"gb37-pair\"><div class=\"gb37-card\"><b>Перед существительным</b><p lang=\"en\">This is <em>my</em> notebook.</p><small>После my сразу идёт noun: notebook.</small></div><div class=\"gb37-card\"><b>Самостоятельно</b><p lang=\"en\">This notebook is <em>mine</em>.</p><small>Mine уже заменяет сочетание my notebook.</small></div></div><div class=\"gb37-example-set\"><div class=\"gb37-example\"><p lang=\"en\">Whose coat is this? — It’s hers.</p><small>Чьё это пальто? — Её.</small></div><div class=\"gb37-example\"><p lang=\"en\">That is our classroom. That classroom is ours.</p><small>Это наш кабинет. Этот кабинет наш.</small></div></div><div class=\"gb37-note\">Конструкция <b>a friend of mine</b> правильна, но <s>a friend of my</s> — нет: после of здесь нужна самостоятельная форма mine.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">05 · Связь с другими формами</div><h3>Они себя? Их? Сами?</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>Что хотим сказать</th><th>Форма</th><th>Пример</th></tr></thead><tbody><tr><td>Кто?</td><td>they</td><td>They are ready.</td></tr><tr><td>Кого? кому?</td><td>them</td><td>I saw them.</td></tr><tr><td>Чей + существительное</td><td>their</td><td>Their project won.</td></tr><tr><td>Чей без существительного</td><td>theirs</td><td>This prize is theirs.</td></tr><tr><td>Самих себя</td><td>themselves</td><td>They prepared themselves.</td></tr></tbody></table></div><div class=\"gb37-note\">Возвратные местоимения (myself, herself...) — отдельная тема. <b>They wash themselves</b> и <b>They wash their car</b> — разные конструкции.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">06 · Типичные ошибки</div><h3>Сравни полное предложение, а не отдельную форму</h3><div class=\"gb37-errors\"><div><span class=\"gb37-wrong\">✕ Me like music.</span><span class=\"gb37-right\">✓ I like music.</span><p>Перед сказуемым, как подлежащее, нужно I.</p></div><div><span class=\"gb37-wrong\">✕ Can you help she?</span><span class=\"gb37-right\">✓ Can you help her?</span><p>После help требуется object pronoun.</p></div><div><span class=\"gb37-wrong\">✕ This is mine bag.</span><span class=\"gb37-right\">✓ This is my bag.</span><p>Перед существительным используется my.</p></div><div><span class=\"gb37-wrong\">✕ The dog wagged it’s tail.</span><span class=\"gb37-right\">✓ The dog wagged its tail.</span><p>Its обозначает принадлежность, it’s = it is/has.</p></div></div></section><div class=\"gb37-outro\"><b>Проверь себя:</b> закрой таблицу и придумай по одному правильному примеру из каждой рассмотренной ситуации. Затем перейди к упражнениям ниже.</div></article>","Артикли a / an / the / нулевой":"<article id=\"rule-theory\" class=\"gb37\" lang=\"ru\"><header class=\"gb37-hero\"><small>БАЗОВАЯ ГРАММАТИКА · КРИСТИНА · ОГЭ 2027</small><h2>Артикли: a/an, the, нулевой артикль</h2><p>Артикль показывает, <b>как говорящий представляет существительное слушателю</b>: как один ещё не определённый предмет, как узнаваемый предмет или как целый класс/вещество. Это не простой список слов «с артиклем» и «без артикля».</p></header><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">01 · Схема</div><h3>Дерево выбора: сначала число и тип существительного</h3><div class=\"gb37-tree\"><div class=\"gb37-tree-head\">1 · Что это за существительное?</div><div class=\"gb37-tree-row\"><div class=\"gb37-branch\"><b>Исчисляемое, единственное число</b><span>dog, book, child</span><div class=\"gb37-tree-row\"><div class=\"gb37-leaf\"><b>Ещё не определено</b><strong>a / an</strong><small>She bought <em>a</em> book.</small></div><div class=\"gb37-leaf\"><b>Понятно, какое именно</b><strong>the</strong><small><em>The</em> book is on the shelf.</small></div></div><small>Существительное в единственном числе обычно требует определителя (a/the/my/this...), если нет особой конструкции.</small></div><div class=\"gb37-branch\"><b>Множественное или неисчисляемое</b><span>books, water, advice</span><div class=\"gb37-tree-row\"><div class=\"gb37-leaf\"><b>Говорим вообще</b><strong>Ø</strong><small><em>Books</em> are useful.</small></div><div class=\"gb37-leaf\"><b>Понятно, о каких именно</b><strong>the</strong><small><em>The</em> books on my desk are new.</small></div></div><small>Вместо Ø могут быть some/any/this/my и другие определители, если этого требует смысл.</small></div></div></div><div class=\"gb37-note\">Схема — отправная точка. <b>My book</b> уже содержит определитель, поэтому <s>the my book</s> нельзя. Имена собственные, профессии, устойчивые выражения и географические названия разбираем отдельно.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">02 · A/an</div><h3>Один предмет, о котором ещё не договорились</h3><div class=\"gb37-example-set\"><div class=\"gb37-example\"><p lang=\"en\">I saw a dog. The dog was sleeping.</p><small>Я увидела собаку. Эта собака спала. Сначала a, затем the.</small></div><div class=\"gb37-example\"><p lang=\"en\">She is a dentist.</p><small>Она стоматолог. Название профессии в единственном числе.</small></div><div class=\"gb37-example\"><p lang=\"en\">He waited for an hour.</p><small>Он ждал час. В hour первый звук гласный.</small></div><div class=\"gb37-example\"><p lang=\"en\">It’s a university.</p><small>Это университет. Первый звук /j/ — согласный.</small></div></div><div class=\"gb37-note\">Выбираем a или an по <b>первому звуку</b> следующего слова, а не по букве: <b>an honest person</b>, <b>a useful tool</b>, <b>an MBA</b>, <b>a European city</b>.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">03 · The</div><h3>Как слушатель определяет нужный предмет?</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>Основание</th><th>Пример</th><th>Почему the</th></tr></thead><tbody><tr><td>Уже упоминали</td><td>I found a key. <b>The key</b> was old.</td><td>Уже знаем, о каком ключе речь.</td></tr><tr><td>Уточняющее выражение</td><td><b>The girl by the window</b> is my sister.</td><td>Описание выделяет конкретную девочку.</td></tr><tr><td>Уникальность в контексте</td><td>Please close <b>the door</b>.</td><td>В комнате ясно, какую дверь закрыть.</td></tr><tr><td>Превосходная степень / порядковый</td><td>It was <b>the best</b> day. / She came <b>the first</b>.</td><td>Конструкция обычно предполагает выбор среди сравниваемых.</td></tr></tbody></table></div><div class=\"gb37-note\">Не только «второе упоминание»: <b>Where’s the teacher?</b> возможно при первом упоминании, если слушатели знают, какой учитель имеется в виду.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">04 · Нулевой</div><h3>Обобщение — не то же самое, что конкретная группа</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>Говорим вообще (Ø)</th><th>Говорим о конкретном (the)</th></tr></thead><tbody><tr><td><b>Cats</b> are curious. — Кошки любопытны.</td><td><b>The cats next door</b> are noisy. — Кошки у соседей шумные.</td></tr><tr><td><b>Water</b> is essential. — Вода необходима.</td><td><b>The water in this glass</b> is cold. — Вода в этом стакане холодная.</td></tr><tr><td>She speaks <b>Spanish</b>. — Она говорит по-испански.</td><td><b>The Spanish in this document</b> is difficult. — Испанский язык в этом документе сложный.</td></tr></tbody></table></div><div class=\"gb37-note\">Если слово неисчисляемое, это <b>не означает</b>, что перед ним никогда не бывает the: важно, обобщение это или конкретный объём/случай.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">05 · Учреждения</div><h3>School, university, prison, hospital: функция или здание</h3><div class=\"gb37-pair\"><div class=\"gb37-card\"><b>Основная социальная функция</b><p lang=\"en\">She is <em>at school</em>.</p><small>Она в школе как ученица.</small></div><div class=\"gb37-card\"><b>Конкретное учреждение/здание</b><p lang=\"en\">She went to <em>the school</em> to talk to a teacher.</p><small>Она пошла в здание школы, чтобы поговорить с учителем.</small></div></div><div class=\"gb37-note\">Различие зависит от смысла, а не только от наличия стен. BrE: <b>in hospital</b> (как пациент). AmE часто: <b>in the hospital</b>. <b>Go to university</b> естественно в BrE; в AmE часто <b>go to college</b>.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">06 · Географические названия</div><h3>Группы названий и исключения</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>Обычно без the</th><th>Обычно с the</th></tr></thead><tbody><tr><td>France, Russia, Canada; London, Ufa</td><td><b>the</b> United Kingdom, <b>the</b> Netherlands, <b>the</b> Philippines</td></tr><tr><td>Lake Baikal, Mount Everest</td><td><b>the</b> Volga, <b>the</b> Thames, <b>the</b> Pacific, <b>the</b> Alps</td></tr><tr><td>Red Square, Central Park</td><td><b>the</b> Sahara, <b>the</b> Suez Canal</td></tr><tr><td>Oxford University, Heathrow Airport</td><td><b>the</b> University of Oxford, <b>the</b> British Museum</td></tr></tbody></table></div><div class=\"gb37-note\">У географических названий есть исключения: нужно учить вместе с самим названием. Не следует выводить правило по одному слову в названии.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">07 · Устойчивые выражения</div><h3>Meals, transport, instruments, time</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>Без артикля (в указанном значении)</th><th>С артиклем / иной смысл</th></tr></thead><tbody><tr><td>have breakfast; have lunch</td><td><b>The lunch we had yesterday</b> was excellent.</td></tr><tr><td>by bus; by train; by car</td><td><b>on the bus; in the car</b></td></tr><tr><td>at home; at work; go to bed</td><td><b>in the house; sit on the bed</b></td></tr><tr><td>play chess; study chemistry</td><td>play <b>the</b> piano (традиционная модель)</td></tr></tbody></table></div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">08 · Разбор ошибок</div><h3>Не исправляй автоматически без смысла</h3><div class=\"gb37-errors\"><div><span class=\"gb37-wrong\">✕ She is doctor.</span><span class=\"gb37-right\">✓ She is a doctor.</span><p>Профессия — исчисляемое единственное число, нужен a/an.</p></div><div><span class=\"gb37-wrong\">✕ I like the cats. (все кошки вообще)</span><span class=\"gb37-right\">✓ I like cats.</span><p>Для целого класса во множественном числе чаще Ø.</p></div><div><span class=\"gb37-wrong\">✕ It is an university.</span><span class=\"gb37-right\">✓ It is a university.</span><p>Начальный звук /j/.</p></div><div><span class=\"gb37-wrong\">✕ We travelled by the train. (способ передвижения)</span><span class=\"gb37-right\">✓ We travelled by train.</span><p>By + транспорт без артикля как способ.</p></div></div><div class=\"gb37-alert\"><b>I like the cats</b> само по себе может быть верным, если речь о конкретных кошках. Ошибка появляется только относительно данного контекста.</div></section><div class=\"gb37-outro\"><b>Проверь себя:</b> закрой таблицу и придумай по одному правильному примеру из каждой рассмотренной ситуации. Затем перейди к упражнениям ниже.</div></article>","Единственное и множественное число":"<article id=\"rule-theory\" class=\"gb37\" lang=\"ru\"><header class=\"gb37-hero\"><small>БАЗОВАЯ ГРАММАТИКА · КРИСТИНА · ОГЭ 2027</small><h2>Единственное и множественное число: формы и значения</h2><p>Сначала определяем, <b>можно ли пересчитать существительное как отдельные предметы</b>, затем выбираем модель множественного числа. В конце важно проверить согласование с глаголом и исключения.</p></header><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">01 · Обычные модели</div><h3>Почему не всегда просто прибавить -s</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>Условие</th><th>Изменение</th><th>Примеры</th></tr></thead><tbody><tr><td>Большинство</td><td>+ <b>-s</b></td><td>book → books; cat → cats</td></tr><tr><td>Звуки /s, z, ʃ, ʒ, tʃ, dʒ/</td><td>+ <b>-es</b></td><td>bus → buses; box → boxes; watch → watches; dish → dishes</td></tr><tr><td>Согласная + y</td><td>y → <b>-ies</b></td><td>city → cities; baby → babies</td></tr><tr><td>Гласная + y</td><td>+ <b>-s</b></td><td>day → days; boy → boys</td></tr><tr><td>Ряд слов на -f/-fe</td><td>-ves</td><td>leaf → leaves; wife → wives; knife → knives</td></tr><tr><td>Ряд слов на -o</td><td>-es</td><td>potato → potatoes; tomato → tomatoes; hero → heroes</td></tr><tr><td>Другие слова на -o</td><td>-s</td><td>photo → photos; piano → pianos; video → videos; radio → radios</td></tr></tbody></table></div><div class=\"gb37-note\">Не переносим -ves на все слова с -f: roof → roofs, belief → beliefs, chief → chiefs, cliff → cliffs, proof → proofs. Volcano → volcanoes / volcanos, оба варианта встречаются.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">02 · Полный учебный перечень</div><h3>Необычные и неизменяемые формы — запомни по группам</h3><p>Ниже <b>полный перечень неправильных форм, включённых в этот учебный справочник</b>, включая школьный минимум и полезные расширенные формы. Это не перечень вообще всех существительных английского языка: он не может быть конечным.</p><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>Единственное число</th><th>Множественное число</th></tr></thead><tbody><tr><td>man</td><td>men</td></tr><tr><td>woman</td><td>women</td></tr><tr><td>child</td><td>children</td></tr><tr><td>person</td><td>people (также persons в официальных контекстах)</td></tr><tr><td>mouse</td><td>mice</td></tr><tr><td>louse</td><td>lice</td></tr><tr><td>foot</td><td>feet</td></tr><tr><td>tooth</td><td>teeth</td></tr><tr><td>goose</td><td>geese</td></tr><tr><td>ox</td><td>oxen</td></tr><tr><td>die (игральная кость)</td><td>dice</td></tr><tr><td>sheep</td><td>sheep</td></tr><tr><td>deer</td><td>deer</td></tr><tr><td>fish</td><td>fish (fishes для видов)</td></tr><tr><td>salmon</td><td>salmon</td></tr><tr><td>trout</td><td>trout</td></tr><tr><td>moose</td><td>moose</td></tr><tr><td>aircraft</td><td>aircraft</td></tr><tr><td>spacecraft</td><td>spacecraft</td></tr><tr><td>species</td><td>species</td></tr><tr><td>series</td><td>series</td></tr><tr><td>means</td><td>means</td></tr><tr><td>offspring</td><td>offspring</td></tr><tr><td>bison</td><td>bison (also bisons)</td></tr><tr><td>swine</td><td>swine</td></tr><tr><td>cactus</td><td>cacti / cactuses</td></tr><tr><td>fungus</td><td>fungi / funguses</td></tr><tr><td>nucleus</td><td>nuclei</td></tr><tr><td>radius</td><td>radii / radiuses</td></tr><tr><td>stimulus</td><td>stimuli</td></tr><tr><td>syllabus</td><td>syllabuses / syllabi</td></tr><tr><td>datum</td><td>data (data часто используется как mass noun)</td></tr><tr><td>bacterium</td><td>bacteria</td></tr><tr><td>medium</td><td>media / mediums (в разных значениях)</td></tr><tr><td>curriculum</td><td>curricula / curriculums</td></tr><tr><td>formula</td><td>formulas / formulae</td></tr><tr><td>criterion</td><td>criteria</td></tr><tr><td>phenomenon</td><td>phenomena</td></tr><tr><td>analysis</td><td>analyses</td></tr><tr><td>basis</td><td>bases</td></tr><tr><td>crisis</td><td>crises</td></tr><tr><td>thesis</td><td>theses</td></tr><tr><td>diagnosis</td><td>diagnoses</td></tr><tr><td>hypothesis</td><td>hypotheses</td></tr><tr><td>axis</td><td>axes</td></tr><tr><td>parenthesis</td><td>parentheses</td></tr><tr><td>oasis</td><td>oases</td></tr><tr><td>index</td><td>indexes / indices (по значению)</td></tr><tr><td>appendix</td><td>appendices / appendixes</td></tr><tr><td>matrix</td><td>matrices / matrixes</td></tr></tbody></table></div><div class=\"gb37-note\">Слова с одинаковой формой в обоих числах не всегда отличаются по смыслу: <b>one sheep / ten sheep</b>, <b>one series / two series</b>. Для person форма people наиболее обычная, persons употребляется в отдельных официальных контекстах.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">03 · -f, -o и внешне похожие слова</div><h3>Две проверки вместо механического правила</h3><div class=\"gb37-pair\"><div class=\"gb37-card\"><b>-f: разные семьи</b><p lang=\"en\">wolf → wolves · roof → roofs · scarf → scarves / scarfs</p><small>Одинаковое окончание основы не гарантирует одинаковый суффикс.</small></div><div class=\"gb37-card\"><b>-o: два основных образца</b><p lang=\"en\">hero → heroes · photo → photos · volcano → volcanoes / volcanos</p><small>Проверяй именно конкретное слово.</small></div></div><div class=\"gb37-note\">Орфографические правила не вычисляются только по последней букве. Поэтому особые формы следует заносить в собственный словарь с примерами.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">04 · Значение числа</div><h3>Нельзя механически прибавить -s ко всему</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>Тип</th><th>Пример</th><th>Что помнить</th></tr></thead><tbody><tr><td>Неисчисляемое</td><td>information, advice, furniture, equipment, homework, news</td><td>Обычно нет формы *informations, *advices и т. п.</td></tr><tr><td>Только множественное в типичных значениях</td><td>scissors, trousers, jeans, shorts, glasses</td><td>These scissors <b>are</b> sharp. A pair of scissors <b>is</b> ...</td></tr><tr><td>Неизменяемая форма</td><td>fish, deer, sheep, species</td><td>Смотри на числительное и сказуемое: two sheep <b>are</b> ...</td></tr><tr><td>Иное значение при -s</td><td>glass → glasses, paper → papers</td><td>Множественное может означать предметы, документы, очки.</td></tr></tbody></table></div><div class=\"gb37-note\">News заканчивается на -s, но грамматически обычно единственное число: <b>The news is good</b>.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">05 · Согласование</div><h3>Сколько предметов — такую форму сказуемого выбираем</h3><div class=\"gb37-example-set\"><div class=\"gb37-example\"><p lang=\"en\">The child is asleep. → The children are asleep.</p><small>Один ребёнок → несколько детей, меняется и сказуемое.</small></div><div class=\"gb37-example\"><p lang=\"en\">A mouse is here. → Two mice are here.</p><small>У неправильной формы тоже множественное согласование.</small></div><div class=\"gb37-example\"><p lang=\"en\">Two pieces of advice are useful.</p><small>Два совета: advice неисчисляемое, считаем «pieces».</small></div></div><div class=\"gb37-note\">Для family, team, police правила отдельные: <b>The police are investigating</b>. Собирательные существительные могут согласовываться по-разному в BrE и AmE, в зависимости от значения.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">06 · Практический алгоритм</div><h3>Как проверять задание ОГЭ 20–28</h3><ol class=\"gb37-steps\"><li>Найди исходное существительное и весь контекст: <b>one, many, two, several</b>, форма глагола.</li><li>Проверь исчисляемость и число: <b>water</b> нельзя механически превратить в *waters в значении «вода вообще».</li><li>Проверь правило написания и список исключений, особенно child/person/mouse/woman/tooth.</li><li>Проверь согласование: <b>children are</b>, а не <s>children is</s>.</li></ol><div class=\"gb37-errors\"><div><span class=\"gb37-wrong\">✕ Two childs were there.</span><span class=\"gb37-right\">✓ Two children were there.</span><p>Child имеет необычную форму children.</p></div><div><span class=\"gb37-wrong\">✕ She gave me three advices.</span><span class=\"gb37-right\">✓ She gave me three pieces of advice.</span><p>Advice неисчисляемое.</p></div><div><span class=\"gb37-wrong\">✕ The news are terrible.</span><span class=\"gb37-right\">✓ The news is terrible.</span><p>News обычно грамматически единственное число.</p></div></div></section><div class=\"gb37-outro\"><b>Проверь себя:</b> закрой таблицу и придумай по одному правильному примеру из каждой рассмотренной ситуации. Затем перейди к упражнениям ниже.</div></article>","Притяжательный падеж":"<article id=\"rule-theory\" class=\"gb37\" lang=\"ru\"><header class=\"gb37-hero\"><small>БАЗОВАЯ ГРАММАТИКА · КРИСТИНА · ОГЭ 2027</small><h2>Притяжательный падеж: чьё это?</h2><p>Задача конструкции <b>’s</b> — связать владельца или источник с тем, что ему принадлежит. Это не то же самое, что <b>is</b>, хотя внешне сокращение выглядит одинаково.</p></header><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">01 · От смысла к форме</div><h3>Кому принадлежит предмет?</h3><div class=\"gb37-ownership\"><span class=\"gb37-owner\">Anna <b>’s</b></span><span class=\"gb37-ownership-arrow\">→</span><span class=\"gb37-owned\">bike</span><small>Чей велосипед? Анны. В английском владелец ставится перед вещью.</small></div><div class=\"gb37-example-set\"><div class=\"gb37-example\"><p lang=\"en\">Anna’s bike is red.</p><small>Велосипед Анны красный.</small></div><div class=\"gb37-example\"><p lang=\"en\">My brother’s friend is here.</p><small>Друг моего брата здесь.</small></div><div class=\"gb37-example\"><p lang=\"en\">The girls’ bags are heavy.</p><small>Сумки девочек тяжёлые.</small></div></div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">02 · Апостроф</div><h3>Четыре разных случая</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>Кто владеет?</th><th>Как писать</th><th>Пример</th></tr></thead><tbody><tr><td>Единственное число</td><td><b>’s</b></td><td>the boy<b>’s</b> phone</td></tr><tr><td>Множественное на -s</td><td>апостроф после s</td><td>the girls<b>’</b> room</td></tr><tr><td>Неправильное множественное без -s</td><td><b>’s</b></td><td>the children<b>’s</b> toys</td></tr><tr><td>Несколько слов / имя</td><td>’s в конце группы</td><td>my mother-in-law<b>’s</b> car</td></tr></tbody></table></div><div class=\"gb37-note\">Имена, заканчивающиеся на s, могут иметь варианты: <b>James’s book</b> и <b>James’ book</b>. В учебном письме придерживайся одного варианта последовательно.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">03 · Один или два владельца?</div><h3>Скобка меняет смысл</h3><div class=\"gb37-pair\"><div class=\"gb37-card\"><b>Общая вещь</b><p lang=\"en\">Tom and Alice<em>’s</em> apartment</p><small>Одна квартира, принадлежащая Тому и Алисе.</small></div><div class=\"gb37-card\"><b>Разные вещи</b><p lang=\"en\">Tom<em>’s</em> and Alice<em>’s</em> apartments</p><small>Квартиры Тома и Алисы по отдельности.</small></div></div><div class=\"gb37-note\">На экзамене проверяй число предметов и контекст. Нельзя делать вывод только по апострофу без смысла.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">04 · ’s и of</div><h3>Когда вместо владельца ставится of</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>Обычно естественнее ’s</th><th>Обычно естественнее of</th></tr></thead><tbody><tr><td>my sister’s phone</td><td>the end of the film</td></tr><tr><td>the teacher’s desk</td><td>the roof of the house</td></tr><tr><td>yesterday’s lesson</td><td>the name of the street</td></tr></tbody></table></div><div class=\"gb37-note\">Это тенденции, а не жёсткий запрет: <b>the car’s engine</b> и <b>the engine of the car</b> возможны, но имеют разную естественность в контексте.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">05 · Не перепутай</div><h3>Притяжательное ’s, сокращение is и множественное -s</h3><div class=\"gb37-example-set\"><div class=\"gb37-example\"><p lang=\"en\">Kate’s book is here.</p><small>Kate’s = «книга Кейт». Притяжательность.</small></div><div class=\"gb37-example\"><p lang=\"en\">Kate’s reading now.</p><small>Kate’s = Kate is. Сокращение глагола.</small></div><div class=\"gb37-example\"><p lang=\"en\">Kates live next door.</p><small>Kates = люди по фамилии Кейт; без апострофа как множественное.</small></div></div><div class=\"gb37-errors\"><div><span class=\"gb37-wrong\">✕ The childrens’ toys</span><span class=\"gb37-right\">✓ The children’s toys</span><p>Children не заканчивается на -s.</p></div><div><span class=\"gb37-wrong\">✕ My parents’s room</span><span class=\"gb37-right\">✓ My parents’ room</span><p>Parents — регулярное множественное на -s.</p></div><div><span class=\"gb37-wrong\">✕ This is her’s.</span><span class=\"gb37-right\">✓ This is hers.</span><p>Притяжательные местоимения hers, ours, theirs пишутся без апострофа.</p></div></div></section><div class=\"gb37-outro\"><b>Проверь себя:</b> закрой таблицу и придумай по одному правильному примеру из каждой рассмотренной ситуации. Затем перейди к упражнениям ниже.</div></article>","Порядок слов в предложении":"<article id=\"rule-theory\" class=\"gb37\" lang=\"ru\"><header class=\"gb37-hero\"><small>БАЗОВАЯ ГРАММАТИКА · КРИСТИНА · ОГЭ 2027</small><h2>Порядок слов: запомни SVOMPT и его границы</h2><p>В нейтральном английском утверждении основной порядок обычно <b>Subject + Verb + Object</b>; добавочные обстоятельства нередко располагаются как <b>Manner → Place → Time</b>. Опорная формула <b>SVOMPT</b> полезна, но она <b>не универсальна</b> для всех предложений.</p></header><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">01 · Опорная схема</div><h3>SVOMPT: кто — делает — что — как — где — когда?</h3><div class=\"gb37-svompt\" role=\"img\" aria-label=\"SVOMPT: Subject, Verb, Object, Manner, Place, Time\"><div class=\"gb37-sv s\"><strong>S</strong><b>My sister</b><small>кто? подлежащее</small></div><div class=\"gb37-sv v\"><strong>V</strong><b>practises</b><small>что делает? сказуемое</small></div><div class=\"gb37-sv o\"><strong>O</strong><b>English</b><small>что? дополнение</small></div><div class=\"gb37-sv m\"><strong>M</strong><b>carefully</b><small>как? образ действия</small></div><div class=\"gb37-sv p\"><strong>P</strong><b>at home</b><small>где? место</small></div><div class=\"gb37-sv t\"><strong>T</strong><b>every evening</b><small>когда? время</small></div></div><div class=\"gb37-note\"><b>My sister practises English carefully at home every evening.</b> — Моя сестра внимательно занимается английским дома каждый вечер. Это учебная опорная модель <b>типичного утвердительного предложения</b>, а не правило, что каждое из шести мест обязательно должно быть заполнено.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">02 · Слова могут отсутствовать</div><h3>Сравни S+V, S+V+O и S+V+Complement</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>Структура</th><th>Пример</th><th>Почему так</th></tr></thead><tbody><tr><td>S + V</td><td>Birds <b>sing</b>.</td><td>Sing может не требовать дополнения.</td></tr><tr><td>S + V + O</td><td>I <b>read books</b>.</td><td>Read здесь имеет прямое дополнение.</td></tr><tr><td>S + be + complement</td><td>She <b>is happy</b>.</td><td>Happy — именная часть сказуемого, не объект.</td></tr><tr><td>S + V + indirect O + direct O</td><td>He <b>gave me a ticket</b>.</td><td>Есть два дополнения: кому? что?</td></tr><tr><td>S + V + O + to + receiver</td><td>He <b>gave a ticket to me</b>.</td><td>Возможен другой способ выражения адресата.</td></tr></tbody></table></div><div class=\"gb37-note\">В <b>She is happy</b> слово happy не O из SVOMPT, а <b>complement</b>. Поэтому схему нельзя механически применять ко всем глаголам.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">03 · Где M, P, T?</div><h3>Переставь обстоятельство и проверь изменение акцента</h3><div class=\"gb37-pair\"><div class=\"gb37-card\"><b>Нейтрально: ... P + T</b><p lang=\"en\">We met <em>at the library yesterday</em>.</p><small>Мы встретились в библиотеке вчера.</small></div><div class=\"gb37-card\"><b>Время в начале</b><p lang=\"en\"><em>Yesterday</em>, we met at the library.</p><small>Вчера мы встретились в библиотеке. Подчёркиваем время.</small></div></div><div class=\"gb37-note\">Обстоятельство <b>времени</b> часто выносится в начало, а <b>образа действия</b> может располагаться рядом с глаголом в зависимости от наречия. Поэтому SVOMPT — подсказка для <i>нейтрального</i> порядка, не железное правило.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">04 · Наречия частотности</div><h3>Usually и never не ставим механически в конец как Time</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>Тип сказуемого</th><th>Позиция</th><th>Пример</th></tr></thead><tbody><tr><td>Обычный глагол</td><td>до смыслового глагола</td><td>I <b>usually</b> walk to school.</td></tr><tr><td>be</td><td>после be</td><td>She is <b>always</b> polite.</td></tr><tr><td>Составное время</td><td>часто после первого вспомогательного</td><td>He has <b>never</b> been there.</td></tr><tr><td>Иногда в начале</td><td>для акцента</td><td><b>Sometimes</b>, we study together.</td></tr></tbody></table></div><div class=\"gb37-note\">Позиция некоторых наречий гибкая. <b>Often</b> может стоять в нескольких позициях; проверяй естественность и конкретный смысл.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">05 · Вопросы и отрицания</div><h3>SVOMPT — только основа, грамматика меняет порядок</h3><div class=\"gb37-example-set\"><div class=\"gb37-example\"><p lang=\"en\">She reads books. → Does she read books?</p><small>Вопрос: does выходит перед подлежащим, reads меняется на read.</small></div><div class=\"gb37-example\"><p lang=\"en\">She is reading. → Is she reading?</p><small>Be выходит перед подлежащим.</small></div><div class=\"gb37-example\"><p lang=\"en\">She does not read books.</p><small>После does not смысловой глагол в основной форме.</small></div></div><div class=\"gb37-note\">Слова <b>not</b>, вопросительные слова и вспомогательные глаголы не укладываются в шесть ячеек SVOMPT. Для них отдельная схема вопроса.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">06 · Подлежащее и дополнение</div><h3>Реальная пара предложений с переменой роли</h3><div class=\"gb37-pair\"><div class=\"gb37-card\"><b>The dog chased the cat.</b><p lang=\"en\">The dog <em>chased</em> the cat.</p><small>Собака погналась за кошкой. S = the dog, O = the cat.</small></div><div class=\"gb37-card\"><b>The cat chased the dog.</b><p lang=\"en\">The cat <em>chased</em> the dog.</p><small>Кошка погналась за собакой. S и O поменялись, смысл противоположный.</small></div></div><div class=\"gb37-note\">Вот что значит «сравни два предложения»: здесь меняется именно <b>роль участников</b> и значение события. Это содержательное сравнение, а не формальный призыв сравнить без примеров.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">07 · Типичные ошибки</div><h3>Что проверить перед письмом ОГЭ</h3><div class=\"gb37-errors\"><div><span class=\"gb37-wrong\">✕ I very like this film.</span><span class=\"gb37-right\">✓ I really like this film.</span><p>В английском really обычно модифицирует глагол like; very не используется прямо перед like в этом значении.</p></div><div><span class=\"gb37-wrong\">✕ She to school goes every day.</span><span class=\"gb37-right\">✓ She goes to school every day.</span><p>Нейтральный порядок: S + V + P + T.</p></div><div><span class=\"gb37-wrong\">✕ He always is late.</span><span class=\"gb37-right\">✓ He is always late.</span><p>С be наречие частоты обычно после связки.</p></div><div><span class=\"gb37-wrong\">✕ I gave to him the book.</span><span class=\"gb37-right\">✓ I gave the book to him. / I gave him the book.</span><p>Для give возможны две основные конструкции с дополнениями.</p></div></div></section><div class=\"gb37-outro\"><b>Проверь себя:</b> закрой таблицу и придумай по одному правильному примеру из каждой рассмотренной ситуации. Затем перейди к упражнениям ниже.</div></article>","Вопросы и краткие ответы":"<article id=\"rule-theory\" class=\"gb37\" lang=\"ru\"><header class=\"gb37-hero\"><small>БАЗОВАЯ ГРАММАТИКА · КРИСТИНА · ОГЭ 2027</small><h2>Вопросы и краткие ответы: сначала найди помощник</h2><p>Чтобы правильно задать вопрос, недостаточно знать <b>do</b>. Нужно определить тип сказуемого: <b>be</b>, простой смысловой глагол, модальный глагол или вспомогательный в составном времени. Краткий ответ повторяет <b>вспомогательный глагол</b>, а не всё предложение.</p></header><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">01 · Дерево решений</div><h3>Какой глагол управляет вопросом?</h3><div class=\"gb37-q-map\"><div class=\"gb37-q-map-head\">Сначала найди сказуемое в утверждении</div><div class=\"gb37-q-grid\"><div><b>be</b><strong>am / is / are / was / were</strong><small>She is tired → <em>Is</em> she tired?</small></div><div><b>Обычный Simple</b><strong>do / does / did</strong><small>She likes tea → <em>Does</em> she like tea?</small></div><div><b>Модальный / will</b><strong>can / must / should / will</strong><small>He can swim → <em>Can</em> he swim?</small></div><div><b>Составное время</b><strong>have / has / had; be</strong><small>She has left → <em>Has</em> she left?</small></div></div></div><div class=\"gb37-note\">Все прямые общие вопросы строятся не по одному шаблону do. Сначала ищем вспомогательный или глагол-связку. Только если его нет в Present/Past Simple со смысловым глаголом, добавляем do/does/did.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">02 · Общие вопросы</div><h3>Сравнение всех основных типов</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>Утверждение</th><th>Вопрос</th><th>Ответ «да»</th><th>Ответ «нет»</th></tr></thead><tbody><tr><td>She <b>is</b> busy.</td><td><b>Is</b> she busy?</td><td>Yes, she is.</td><td>No, she isn’t.</td></tr><tr><td>They <b>were</b> ready.</td><td><b>Were</b> they ready?</td><td>Yes, they were.</td><td>No, they weren’t.</td></tr><tr><td>He <b>plays</b> chess.</td><td><b>Does</b> he play chess?</td><td>Yes, he does.</td><td>No, he doesn’t.</td></tr><tr><td>You <b>visited</b> them.</td><td><b>Did</b> you visit them?</td><td>Yes, I did.</td><td>No, I didn’t.</td></tr><tr><td>She <b>can</b> skate.</td><td><b>Can</b> she skate?</td><td>Yes, she can.</td><td>No, she can’t.</td></tr><tr><td>They <b>will</b> come.</td><td><b>Will</b> they come?</td><td>Yes, they will.</td><td>No, they won’t.</td></tr><tr><td>She <b>is studying</b>.</td><td><b>Is</b> she studying?</td><td>Yes, she is.</td><td>No, she isn’t.</td></tr><tr><td>He <b>has finished</b>.</td><td><b>Has</b> he finished?</td><td>Yes, he has.</td><td>No, he hasn’t.</td></tr><tr><td>She <b>has got</b> a bike.</td><td><b>Has</b> she got a bike?</td><td>Yes, she has.</td><td>No, she hasn’t.</td></tr></tbody></table></div><div class=\"gb37-note\">В кратком утвердительном ответе обычно нельзя сократить вспомогательный после местоимения: <b>Yes, she is</b>, не <s>Yes, she’s</s>; <b>Yes, I have</b>, не <s>Yes, I’ve</s>.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">03 · Специальные вопросы</div><h3>Кто? где? когда? почему? какие?</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>Вопросительное слово</th><th>О чём спрашиваем</th><th>Пример</th></tr></thead><tbody><tr><td>who</td><td>человек</td><td>Who is at the door? — It’s Emma.</td></tr><tr><td>what</td><td>предмет/действие</td><td>What did she buy? — A notebook.</td></tr><tr><td>where</td><td>место</td><td>Where does he live? — In Ufa.</td></tr><tr><td>when</td><td>время</td><td>When will they arrive? — Tomorrow.</td></tr><tr><td>why</td><td>причина</td><td>Why is she upset? — Because she lost her keys.</td></tr><tr><td>how</td><td>способ/состояние</td><td>How did you get here? — By train.</td></tr><tr><td>which</td><td>выбор из вариантов</td><td>Which bag do you prefer? — The blue one.</td></tr><tr><td>whose</td><td>принадлежность</td><td>Whose phone is this? — Mine.</td></tr></tbody></table></div><div class=\"gb37-note\">Специальный вопрос обычно <b>не является</b> вопросом «да/нет»; отвечай требуемой информацией. На <b>Where do you live?</b> ответ <i>Yes, I do</i> грамматически не отвечает на вопрос.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">04 · Важное исключение</div><h3>Who/what как подлежащее: do может не понадобиться</h3><div class=\"gb37-pair\"><div class=\"gb37-card\"><b>Who = подлежащее</b><p lang=\"en\"><em>Who</em> called you? — Anna.</p><small>Who само выполняет действие. Не: Who did call you? в нейтральном вопросе.</small></div><div class=\"gb37-card\"><b>Who = дополнение</b><p lang=\"en\"><em>Who did</em> you call? — Anna.</p><small>You выполняет действие, Who обозначает объект.</small></div></div><div class=\"gb37-note\">В нейтральных вопросах <b>Who came?</b> и <b>What happened?</b> нет обычной инверсии. <b>Who did call?</b> встречается как эмфатический вариант с особым ударением, поэтому нельзя утверждать, что это всегда невозможно.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">05 · Когда короткое Yes/No не подходит</div><h3>Уточняем вопрос — не подменяем ответ</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>Тип вопроса</th><th>Что нужно в ответе</th><th>Пример</th></tr></thead><tbody><tr><td>Wh-вопрос</td><td>Информация</td><td>When did you arrive? — On Sunday.</td></tr><tr><td>Альтернативный вопрос</td><td>Выбор варианта</td><td>Tea or coffee? — Coffee, please.</td></tr><tr><td>Вопрос к подлежащему</td><td>Имя / предмет</td><td>Who broke the vase? — Max.</td></tr><tr><td>Косвенный вопрос</td><td>Содержание ответа</td><td>Do you know where she lives? — Yes, I do. / In Ufa, I think.</td></tr><tr><td>Вежливая просьба</td><td>Согласие/отказ по смыслу</td><td>Could you open the window? — Sure. / Sorry, I can’t.</td></tr></tbody></table></div><div class=\"gb37-note\">Важно: <b>Do you know where she lives?</b> по форме — общий вопрос о твоём знании, поэтому <b>Yes, I do</b> грамматически возможно. Но это <b>не сообщает адрес</b>, если собеседник ждёт именно адрес.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">06 · Отрицательные вопросы и вопросы с хвостиком</div><h3>Почему короткий ответ может сбивать с толку</h3><div class=\"gb37-example-set\"><div class=\"gb37-example\"><p lang=\"en\">Don’t you like tea? — No, I don’t.</p><small>Разве тебе не нравится чай? — Нет, не нравится.</small></div><div class=\"gb37-example\"><p lang=\"en\">You’re ready, aren’t you? — Yes, I am.</p><small>Ты готова, правда? — Да.</small></div><div class=\"gb37-example\"><p lang=\"en\">She doesn’t smoke, does she? — No, she doesn’t.</p><small>Она ведь не курит? — Нет, не курит.</small></div></div><div class=\"gb37-note\">В английском <b>Yes / No</b> обычно выражает факт: <b>Yes, I do</b> = люблю/делаю; <b>No, I don’t</b> = не люблю/не делаю, даже если вопрос отрицательный.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">07 · Косвенный порядок</div><h3>Do you know where ...? — без обратного порядка во вложенной части</h3><div class=\"gb37-pair\"><div class=\"gb37-card\"><b>Прямой</b><p lang=\"en\">Where <em>does</em> she <em>live</em>?</p><small>Где она живёт?</small></div><div class=\"gb37-card\"><b>Встроенный</b><p lang=\"en\">Do you know where she <em>lives</em>?</p><small>Ты знаешь, где она живёт?</small></div></div><div class=\"gb37-note\">Неверно: <s>Do you know where does she live?</s> Внутри встроенного вопроса порядок как в утверждении: <b>where she lives</b>.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">08 · Ошибки</div><h3>Проверяем помощник и форму глагола</h3><div class=\"gb37-errors\"><div><span class=\"gb37-wrong\">✕ Does he likes jazz?</span><span class=\"gb37-right\">✓ Does he like jazz?</span><p>После does — базовая форма.</p></div><div><span class=\"gb37-wrong\">✕ Do you are ready?</span><span class=\"gb37-right\">✓ Are you ready?</span><p>Be не требует do.</p></div><div><span class=\"gb37-wrong\">✕ Where she lives? (прямой вопрос)</span><span class=\"gb37-right\">✓ Where does she live?</span><p>Нужна инверсия с does.</p></div><div><span class=\"gb37-wrong\">✕ Yes, she’s.</span><span class=\"gb37-right\">✓ Yes, she is.</span><p>В кратком ответе не сокращаем is таким образом.</p></div><div><span class=\"gb37-wrong\">✕ Where did he went?</span><span class=\"gb37-right\">✓ Where did he go?</span><p>После did — базовая форма.</p></div></div></section><div class=\"gb37-outro\"><b>Проверь себя:</b> закрой таблицу и придумай по одному правильному примеру из каждой рассмотренной ситуации. Затем перейди к упражнениям ниже.</div></article>","Повелительное наклонение":"<article id=\"rule-theory\" class=\"gb37\" lang=\"ru\"><header class=\"gb37-hero\"><small>БАЗОВАЯ ГРАММАТИКА · КРИСТИНА · ОГЭ 2027</small><h2>Повелительное наклонение: просьба, инструкция, запрет</h2><p>Английское повелительное наклонение употребляется, когда говорящий просит, предупреждает, предлагает или инструктирует. Форма часто начинается с <b>основной формы глагола</b>, а подлежащее you обычно не произносится.</p></header><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">01 · Для чего нужна форма</div><h3>Одни слова — разные коммуникативные цели</h3><div class=\"gb37-pair\"><div class=\"gb37-card\"><b>Инструкция</b><p lang=\"en\"><em>Open</em> the book at page ten.</p><small>Открой учебник на десятой странице.</small></div><div class=\"gb37-card\"><b>Предупреждение</b><p lang=\"en\"><em>Be careful!</em></p><small>Будь осторожна!</small></div><div class=\"gb37-card\"><b>Просьба</b><p lang=\"en\"><em>Please, wait</em> here.</p><small>Пожалуйста, подожди здесь.</small></div><div class=\"gb37-card\"><b>Запрет</b><p lang=\"en\"><em>Don’t touch</em> the screen.</p><small>Не трогай экран.</small></div></div><div class=\"gb37-note\">Вежливость зависит от интонации, контекста и слов <b>please</b>, <b>could you ...?</b>. Голый императив в некоторых ситуациях звучит слишком резко.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">02 · Схема формы</div><h3>Утверждение / отрицание / let’s</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>Функция</th><th>Формула</th><th>Пример</th></tr></thead><tbody><tr><td>Сделай</td><td>base verb + ...</td><td><b>Turn</b> left.</td></tr><tr><td>Не делай</td><td>Don’t + base verb</td><td><b>Don’t turn</b> left.</td></tr><tr><td>Будь / не будь</td><td>Be / Don’t be + adjective</td><td><b>Be</b> quiet. / <b>Don’t be</b> late.</td></tr><tr><td>Давай(те)</td><td>Let’s + base verb</td><td><b>Let’s go</b> home.</td></tr><tr><td>Давай(те) не</td><td>Let’s not + base verb</td><td><b>Let’s not argue</b>.</td></tr></tbody></table></div><div class=\"gb37-note\">Let’s = let us в предложении-совете. Это отдельный тип «давай(те)», не то же самое, что приказ одному человеку.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">03 · Вежливость</div><h3>Сравни одинаковое действие, разное отношение</h3><div class=\"gb37-example-set\"><div class=\"gb37-example\"><p lang=\"en\">Close the window.</p><small>Закрой окно. Прямое указание.</small></div><div class=\"gb37-example\"><p lang=\"en\">Please close the window.</p><small>Пожалуйста, закрой окно. Вежливее.</small></div><div class=\"gb37-example\"><p lang=\"en\">Could you close the window, please?</p><small>Не мог(ла) бы ты закрыть окно? Вежливая просьба-вопрос.</small></div></div><div class=\"gb37-note\">Не считай <b>Close the window</b> грамматической ошибкой: проблема может быть именно в тоне общения.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">04 · Нюансы</div><h3>You и отрицания</h3><div class=\"gb37-example-set\"><div class=\"gb37-example\"><p lang=\"en\">You stay here; I’ll call for help.</p><small>Ты оставайся здесь, а я позову помощь. You возможно для акцента или противопоставления.</small></div><div class=\"gb37-example\"><p lang=\"en\">Never give up.</p><small>Никогда не сдавайся.</small></div><div class=\"gb37-example\"><p lang=\"en\">Don’t forget to lock the door.</p><small>Не забудь закрыть дверь.</small></div></div><div class=\"gb37-note\">Краткий ответ на побуждение обычно не имеет формы Yes, I do: часто говорят <b>OK</b>, <b>Sure</b>, <b>I will</b>, <b>Sorry, I can’t</b> в зависимости от смысла.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">05 · Ошибки</div><h3>Без to и без вспомогательного do в утвердительной форме</h3><div class=\"gb37-errors\"><div><span class=\"gb37-wrong\">✕ To open the book!</span><span class=\"gb37-right\">✓ Open the book!</span><p>Обычный императив начинается с base form.</p></div><div><span class=\"gb37-wrong\">✕ No touch this!</span><span class=\"gb37-right\">✓ Don’t touch this!</span><p>Запрет обычно оформляется через Don’t.</p></div><div><span class=\"gb37-wrong\">✕ Let’s to go.</span><span class=\"gb37-right\">✓ Let’s go.</span><p>После let’s следует base verb.</p></div></div></section><div class=\"gb37-outro\"><b>Проверь себя:</b> закрой таблицу и придумай по одному правильному примеру из каждой рассмотренной ситуации. Затем перейди к упражнениям ниже.</div></article>","Предлоги времени":"<article id=\"rule-theory\" class=\"gb37\" lang=\"ru\"><header class=\"gb37-hero\"><small>БАЗОВАЯ ГРАММАТИКА · КРИСТИНА · ОГЭ 2027</small><h2>Предлоги времени: in, on, at и случаи без предлога</h2><p>Предлог зависит от <b>того, как устроено обозначение времени</b>: большой период, календарная дата или точная точка. Это смысловая подсказка, но для устойчивых выражений нужны отдельные правила.</p></header><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">01 · Масштаб времени</div><h3>От широкого периода к точному моменту</h3><div class=\"gb37-time-scale\"><div><strong>IN</strong><b>месяц · год · время года</b><small>in October · in 2027 · in winter</small></div><div><strong>ON</strong><b>день · дата · конкретный день + часть суток</b><small>on Friday · on 20 October · on Monday morning</small></div><div><strong>AT</strong><b>время на часах · точка</b><small>at 7:30 · at noon · at midnight</small></div></div><div class=\"gb37-note\">Говорим <b>on Friday at 7:30 in the evening</b>: в одной фразе три указания разной точности.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">02 · По типу выражения</div><h3>Большая таблица употребления</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>IN</th><th>ON</th><th>AT</th></tr></thead><tbody><tr><td>in 2027</td><td>on Monday</td><td>at 6 pm</td></tr><tr><td>in July</td><td>on 1 May</td><td>at midday / at noon</td></tr><tr><td>in spring</td><td>on New Year’s Day</td><td>at midnight</td></tr><tr><td>in the morning</td><td>on Friday morning</td><td>at night</td></tr><tr><td>in the afternoon</td><td>on my birthday</td><td>at the weekend (BrE)</td></tr><tr><td>in the evening</td><td>on Christmas Day</td><td>at Christmas (период праздника)</td></tr></tbody></table></div><div class=\"gb37-note\">В американском английском обычно <b>on the weekend</b>, в британском часто <b>at the weekend</b>. Некоторые устойчивые сочетания различаются по диалекту.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">03 · Никакого предлога</div><h3>Last, next, this, every</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>Неверно (в обычном обстоятельстве времени)</th><th>Правильно</th></tr></thead><tbody><tr><td>in last Monday</td><td>last Monday</td></tr><tr><td>in next week</td><td>next week</td></tr><tr><td>on this morning</td><td>this morning</td></tr><tr><td>at every summer</td><td>every summer</td></tr><tr><td>on yesterday</td><td>yesterday</td></tr><tr><td>in tomorrow</td><td>tomorrow</td></tr></tbody></table></div><div class=\"gb37-note\">Эти слова сами выражают временную отнесённость. Не добавляй in/on/at механически.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">04 · Когда меняется смысл</div><h3>At Christmas vs on Christmas Day</h3><div class=\"gb37-pair\"><div class=\"gb37-card\"><b>Период праздника</b><p lang=\"en\">We visit our relatives <em>at Christmas</em>.</p><small>Мы навещаем родных в рождественские праздники.</small></div><div class=\"gb37-card\"><b>Конкретная дата</b><p lang=\"en\">We met <em>on Christmas Day</em>.</p><small>Мы встретились в день Рождества.</small></div></div><div class=\"gb37-note\">Так же <b>in the morning</b> (вообще утром), но <b>on Monday morning</b> (в понедельник утром).</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">05 · Другие предлоги времени</div><h3>Since / for / by / until / during / from ... to</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>Конструкция</th><th>Значение</th><th>Пример</th></tr></thead><tbody><tr><td>for</td><td>продолжительность</td><td>for two hours — два часа</td></tr><tr><td>since</td><td>точка отсчёта</td><td>since Monday — с понедельника</td></tr><tr><td>by</td><td>не позднее</td><td>by Friday — к пятнице</td></tr><tr><td>until / till</td><td>вплоть до</td><td>until 6 pm — до шести</td></tr><tr><td>during</td><td>в течение события/периода</td><td>during the lesson — во время урока</td></tr><tr><td>from ... to ...</td><td>границы периода</td><td>from 9 to 11 — с 9 до 11</td></tr></tbody></table></div><div class=\"gb37-note\">Разница важна: <b>Finish by Friday</b> = завершить не позже пятницы; <b>Work until Friday</b> = работать вплоть до пятницы.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">06 · Ошибки</div><h3>Определи тип временной единицы</h3><div class=\"gb37-errors\"><div><span class=\"gb37-wrong\">✕ in Monday</span><span class=\"gb37-right\">✓ on Monday</span><p>День недели → on.</p></div><div><span class=\"gb37-wrong\">✕ at 2027</span><span class=\"gb37-right\">✓ in 2027</span><p>Год → in.</p></div><div><span class=\"gb37-wrong\">✕ on 7.15</span><span class=\"gb37-right\">✓ at 7.15</span><p>Точное время → at.</p></div><div><span class=\"gb37-wrong\">✕ in last week</span><span class=\"gb37-right\">✓ last week</span><p>После last предлог обычно не нужен.</p></div><div><span class=\"gb37-wrong\">✕ on the weekend всегда неправильно</span><span class=\"gb37-right\">✓ on the weekend (AmE)</span><p>Учитывай разновидность английского: at the weekend (BrE), on the weekend (AmE).</p></div></div></section><div class=\"gb37-outro\"><b>Проверь себя:</b> закрой таблицу и придумай по одному правильному примеру из каждой рассмотренной ситуации. Затем перейди к упражнениям ниже.</div></article>","Предлоги места и движения":"<article id=\"rule-theory\" class=\"gb37\" lang=\"ru\"><header class=\"gb37-hero\"><small>БАЗОВАЯ ГРАММАТИКА · КРИСТИНА · ОГЭ 2027</small><h2>Предлоги места и движения: где и куда?</h2><p>Главное различие: <b>где находится объект</b> (место) и <b>куда/как он перемещается</b> (направление). <b>In</b> не всегда означает «в», а <b>on</b> — не всегда «на»: важно пространственное отношение.</p></header><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">01 · Пространственная модель</div><h3>Внутри · на поверхности · в точке</h3><div class=\"gb37-place\"><div><strong>IN</strong><span class=\"gb37-place-in\"><i>●</i></span><b>внутри границ</b><small>in a room; in a box; in Moscow</small></div><div><strong>ON</strong><span class=\"gb37-place-on\"><i>●</i></span><b>на поверхности</b><small>on a table; on the wall</small></div><div><strong>AT</strong><span class=\"gb37-place-at\"><i>●</i></span><b>конкретная точка / функция</b><small>at a bus stop; at school; at home</small></div></div><div class=\"gb37-note\">Простая картинка — мнемоника, а не полное правило. Например, <b>on the bus</b> используется для общественного транспорта, хотя пассажир физически находится внутри.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">02 · Место</div><h3>Примеры с подробными различиями</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>IN — границы</th><th>ON — контакт/поверхность</th><th>AT — точка/функция</th></tr></thead><tbody><tr><td>in the garden</td><td>on the grass</td><td>at the gate</td></tr><tr><td>in a car / in a taxi</td><td>on a bus / on a train</td><td>at the station</td></tr><tr><td>in England / in Ufa</td><td>on the first floor</td><td>at 22 Baker Street</td></tr><tr><td>in a photo</td><td>on the screen</td><td>at the entrance</td></tr></tbody></table></div><div class=\"gb37-note\">Не каждую ситуацию можно вывести из геометрии: <b>in a photo</b>, <b>on a screen</b>, <b>at school</b> часто требуют запоминания типичного употребления.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">03 · Место ↔ направление</div><h3>In / into; on / onto; at / to</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>Где? (положение)</th><th>Куда? (движение)</th><th>Смысл</th></tr></thead><tbody><tr><td>The cat is <b>in</b> the box.</td><td>The cat jumped <b>into</b> the box.</td><td>Внутри ↔ внутрь</td></tr><tr><td>The book is <b>on</b> the desk.</td><td>Put the book <b>onto</b> the desk.</td><td>На поверхности ↔ движение на неё</td></tr><tr><td>We are <b>at</b> the station.</td><td>We are going <b>to</b> the station.</td><td>Место пребывания ↔ направление</td></tr><tr><td>He is <b>in</b> the room.</td><td>He walked <b>out of</b> the room.</td><td>Место ↔ движение наружу</td></tr></tbody></table></div><div class=\"gb37-note\">В повседневной речи <b>on</b> может использоваться и с движением: <b>Put it on the table</b> — правильно. Onto явно подчёркивает перемещение на поверхность.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">04 · At vs in: одно учреждение</div><h3>Функция или физическое нахождение?</h3><div class=\"gb37-pair\"><div class=\"gb37-card\"><b>At school</b><p lang=\"en\">My daughter is <em>at school</em>.</p><small>Она в школе (учится / находится там как в учебном учреждении).</small></div><div class=\"gb37-card\"><b>In the school</b><p lang=\"en\">The cleaners are <em>in the school</em>.</p><small>Уборщики находятся внутри здания школы.</small></div></div><div class=\"gb37-note\">В некоторых ситуациях <b>at</b> и <b>in</b> оба допустимы, но меняется фокус высказывания. Нельзя объявлять один вариант ошибкой без контекста.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">05 · Движение</div><h3>Across, through, along, past, over, under</h3><div class=\"gb37-example-set\"><div class=\"gb37-example\"><p lang=\"en\">She walked across the road.</p><small>Она перешла дорогу с одной стороны на другую.</small></div><div class=\"gb37-example\"><p lang=\"en\">We walked through the tunnel.</p><small>Мы прошли через туннель (внутри него).</small></div><div class=\"gb37-example\"><p lang=\"en\">Walk along the river.</p><small>Иди вдоль реки.</small></div><div class=\"gb37-example\"><p lang=\"en\">Go past the cinema.</p><small>Пройди мимо кинотеатра.</small></div><div class=\"gb37-example\"><p lang=\"en\">The bird flew over the lake.</p><small>Птица пролетела над озером.</small></div><div class=\"gb37-example\"><p lang=\"en\">The cat crawled under the fence.</p><small>Кошка пролезла под забором.</small></div></div><div class=\"gb37-note\">Across и through отвечают на разные пространственные отношения: <b>across a field</b> (через открытое пространство), <b>through a forest</b> (сквозь пространство с окружением).</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">06 · Транспорт</div><h3>In a car / on a bus / by bus</h3><div class=\"gb37-table-scroll\"><table class=\"gb37-table\"><thead><tr><th>Внутри / на транспортном средстве</th><th>Способ передвижения</th></tr></thead><tbody><tr><td>in a car / in a taxi</td><td>by car / by taxi</td></tr><tr><td>on a bus / on a train / on a plane</td><td>by bus / by train / by plane</td></tr><tr><td>on a bike / on a motorcycle</td><td>by bike / by motorcycle</td></tr></tbody></table></div><div class=\"gb37-note\">В <b>by car</b> обычно нет артикля, потому что речь о способе передвижения. <b>In the car</b> может указывать на конкретную машину.</div></section><section class=\"gb37-chapter\"><div class=\"gb37-eyebrow\">07 · Типичные ошибки</div><h3>Движение vs состояние</h3><div class=\"gb37-errors\"><div><span class=\"gb37-wrong\">✕ We are going at the museum.</span><span class=\"gb37-right\">✓ We are going to the museum.</span><p>To указывает направление движения.</p></div><div><span class=\"gb37-wrong\">✕ The keys are on my bag. (внутри сумки)</span><span class=\"gb37-right\">✓ The keys are in my bag.</span><p>Если ключи внутри, используем in.</p></div><div><span class=\"gb37-wrong\">✕ I go by the bus. (способ)</span><span class=\"gb37-right\">✓ I go by bus.</span><p>By + транспорт без артикля в значении способа.</p></div><div><span class=\"gb37-wrong\">✕ He walked across the tunnel. (по туннелю внутри)</span><span class=\"gb37-right\">✓ He walked through the tunnel.</span><p>Through подчёркивает движение внутри ограниченного пространства.</p></div></div></section><div class=\"gb37-outro\"><b>Проверь себя:</b> закрой таблицу и придумай по одному правильному примеру из каждой рассмотренной ситуации. Затем перейди к упражнениям ниже.</div></article>"};
 const all=new Map(p.grammarGroups.flatMap(g=>g.topics.map(x=>[x.title,x.id])));
 const old=ref.guides['to be'];
 let installed=0;const errors=[];
 for(const [title,theory] of Object.entries(pages)){
   try{
     if(!all.has(title)) throw Error('No such catalog topic');
     const prev=ref.guides[title];
     if(!prev || !Array.isArray(prev.levels) || !prev.levels.length) throw Error('Missing exercise source');
     // Replace just presentation/theory: exact progress keys and levels survive.
     ref.guides[title]={...prev,theory,gb37:true};installed++;
   }catch(e){errors.push({title,error:String(e.message||e)})}
 }
 window.OGE_GRAMMAR_FOUNDATIONS_V37={installed,requested:Object.keys(pages).length,errors,unchangedToBe:ref.guides['to be']===old,topics:Object.keys(pages)};
 if(errors.length)console.error('v37 issues',errors);
})();
